// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance + 1);
        vm.deal(address(c), amount);
        vm.startPrank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", nonOwner));
        vm.stopPrank();
        assertTrue(!ok, "Non-owner must not be able to withdraw");
    }
}

contract Attacker {
    Phishable public target;
    constructor(Phishable _target) { target = _target; }
    receive() external payable {
        target.withdrawAll(address(this));
    }
}
